import {test,expect} from 'vitest';
import {startRuntime,feishu} from '/Users/gerayeremin/Documents/deepseek-harness/default-workspace/dsh-superagent/.worktrees/model-fallback-bounds-ff97608c4932/tests/fixtures/host.ts';
import {ModelRoutingConfigSchema} from '/Users/gerayeremin/Documents/deepseek-harness/default-workspace/dsh-superagent/.worktrees/model-fallback-bounds-ff97608c4932/src/policy.ts';
import {ToolExecutionLedger} from '/Users/gerayeremin/Documents/deepseek-harness/default-workspace/dsh-superagent/.worktrees/model-fallback-bounds-ff97608c4932/src/model-routing.ts';
test('real runtime honors total one-attempt limit even when another fallback is eligible',async()=>{
const h=await startRuntime();try{
const google={provider:'antigravity',model:'gemini-3.8-flash',starred:true};const sonnet={provider:'anthropic',model:'claude-sonnet-5-5',starred:true};
await h.runtime.settings.save('models',{hierarchy:[google,sonnet],maxEscalations:1,routing:ModelRoutingConfigSchema.parse({primary:{provider:google.provider,model:google.model},fallbacks:[{provider:sonnet.provider,model:sonnet.model}],max_total_attempts:1,max_attempts_per_model:1})},h.runtime.store.blockRevision('models'),'panel');
const one=await h.acceptedTicket(feishu('review-no-substitution','@bot Fix isolated audit fixture'));
const agent=h.agents.get(one.sessionId)!;const session=agent.session as any;const before=session.append.mock.calls.filter(([e]:any)=>e==='model/selection').length;
h.ctx.emit('agent/error',{agent,error:Object.assign(new Error('Google quota exhausted'),{status:429})} as never);await h.runtime.idle(); for(let i=0;i<10;i++){await new Promise(resolve=>setImmediate(resolve));await h.runtime.idle();}
const later=session.append.mock.calls.filter(([e]:any)=>e==='model/selection').slice(before).map(([,v]:any)=>v);
(await import('node:fs')).writeFileSync('/private/tmp/pr121-runtime-observation.json',JSON.stringify({later,settings:h.runtime.store.settings().models,ticket:h.runtime.store.tickets.get(one.ticket.id)}));expect(later).toHaveLength(0);
}finally{await h.stop();}});
test('ledger prevents a second start while identical tool outcome remains in flight',()=>{
const ledger=new ToolExecutionLedger();ledger.recordStart('effect-1','write');expect(()=>ledger.recordStart('effect-1','write')).toThrow();
});

